<?php
namespace Database\Seeders;use App\Models\{Institution,ProjectProfile,SystemThreshold};use Illuminate\Database\Seeder;
class ProjectAlignmentSeeder extends Seeder{public function run():void{$institution=Institution::where('slug','university-of-lagos')->orWhere('name','Adekunle Ajasin University, Akungba')->first();if($institution){$institution->update(['name'=>'Adekunle Ajasin University, Akungba','slug'=>'aaua-akungba','type'=>'university','timezone'=>'Africa/Lagos']);}else{$institution=Institution::firstOrCreate(['slug'=>'aaua-akungba'],['name'=>'Adekunle Ajasin University, Akungba','type'=>'university','timezone'=>'Africa/Lagos']);}ProjectProfile::where('is_active',true)->update(['is_active'=>false]);ProjectProfile::create(['institution_id'=>$institution->id,'project_title'=>'Optimization of Campus-Wide Wi-Fi Coverage Using RF Heat Mapping and Load Analysis','aim'=>'To optimize the performance of the campus-wide Wi-Fi network by integrating RF signal coverage analysis, RF heat mapping and network load analysis.','objectives'=>['Identify coverage gaps, interference zones and congested areas.','Analyse network load and user distribution across wireless access points.','Evaluate Wi-Fi signal strength across selected campus locations using RF heat mapping.'],'scope'=>['Selected academic buildings','Selected residential buildings','Selected administrative buildings','RSSI coverage','AP load','User experience'],'limitations'=>['Time and available survey devices','Dynamic network conditions','Wired infrastructure and external ISP issues are outside scope'],'methodology'=>['Real RSSI and performance measurements','IDW spatial interpolation','AP load and channel utilisation analysis','User feedback correlation','Deterministic explainable rules'],'specification_version'=>'1.1','is_active'=>true]);foreach([['rssi_weak_dbm',-75,'dBm'],['throughput_good_mbps',25,'Mbps'],['latency_good_ms',50,'ms'],['packet_loss_good_percent',1,'percent'],['channel_utilisation_high_percent',70,'percent']] as[$key,$value,$unit])SystemThreshold::updateOrCreate(['key'=>$key],compact('value','unit'));}}
